import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaPlus, FaEdit, FaTrash, FaSearch, FaUser } from 'react-icons/fa';
import axios from 'axios';
import './Actors.css';
import { toPersianDigits } from '../utils/locale';

const Actors: React.FC = () => {
  const [actors, setActors] = useState([]);
  const [filteredActors, setFilteredActors] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [presets, setPresets] = useState<Array<{ name: string; search: string; role: string }>>([]);
  const [presetName, setPresetName] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchActors();
    const saved = localStorage.getItem('actors_filter_presets');
    if (saved) { try { setPresets(JSON.parse(saved)); } catch { } }
  }, []);

  useEffect(() => {
    filterActors();
  }, [actors, searchTerm]);

  const fetchActors = async () => {
    try {
      const response = await axios.get('/api/actors');
      setActors(response.data);
    } catch (error) {
      toast.error('خطا در دریافت لیست عوامل');
    } finally {
      setLoading(false);
    }
  };

  const filterActors = () => {
    let filtered = actors;

    if (searchTerm) {
      filtered = filtered.filter((actor: any) =>
        actor.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        actor.role?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        actor.phone?.includes(searchTerm) ||
        actor.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (roleFilter) {
      filtered = filtered.filter((actor: any) => (actor.role || '').toLowerCase() === roleFilter.toLowerCase());
    }

    setFilteredActors(filtered);
  };

  const savePreset = () => {
    if (!presetName.trim()) { toast.error('نام پرِست را وارد کنید'); return; }
    const next = presets.filter(p => p.name !== presetName).concat([{ name: presetName, search: searchTerm, role: roleFilter }]);
    setPresets(next);
    localStorage.setItem('actors_filter_presets', JSON.stringify(next));
    toast.success('پرِست ذخیره شد');
  };

  const applyPreset = (name: string) => {
    const p = presets.find(pp => pp.name === name);
    if (p) { setSearchTerm(p.search); setRoleFilter(p.role); }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('آیا از حذف این عامل مطمئن هستید؟')) {
      try {
        await axios.delete(`/api/actors/${id}`);
        toast.success('عامل با موفقیت حذف شد');
        fetchActors();
      } catch (error) {
        toast.error('خطا در حذف عامل');
      }
    }
  };

  if (loading) {
    return (
      <div className="actors-container">
        <div className="page-header">
          <h1>مدیریت عوامل</h1>
          <button className="btn btn-success" disabled>
            <FaPlus />
            عامل جدید
          </button>
        </div>
        <div className="filters-section skeleton-block" />
        <div className="actors-grid">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="actor-card skeleton">
              <div className="card-header">
                <div className="actor-info">
                  <div className="actor-avatar skeleton-avatar" />
                  <div style={{ flex: 1 }}>
                    <div className="skeleton-title" />
                    <div className="skeleton-small" />
                  </div>
                </div>
                <div className="card-actions">
                  <div className="skeleton-small" style={{ width: 35, height: 35 }} />
                  <div className="skeleton-small" style={{ width: 35, height: 35 }} />
                </div>
              </div>
              <div className="card-content">
                <div className="skeleton-line" />
                <div className="skeleton-line" />
                <div className="skeleton-line short" />
              </div>
              <div className="card-footer">
                <div className="skeleton-small" />
                <div className="skeleton-badge" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="actors-container">
      <div className="page-header">
        <h1>مدیریت عوامل</h1>
        <Link to="/actors/new" className="btn btn-success">
          <FaPlus />
          عامل جدید
        </Link>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <FaSearch />
          <input
            type="text"
            placeholder="جستجو در نام، نقش، تلفن یا ایمیل..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
        <div className="status-filter" style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <input
            type="text"
            placeholder="فیلتر نقش دقیق (مثلاً کارگردان)"
            value={roleFilter}
            onChange={(e) => setRoleFilter(e.target.value)}
            className="search-input"
            style={{ maxWidth: '240px' }}
          />
          <input type="text" value={presetName} onChange={(e) => setPresetName(e.target.value)} placeholder="نام پرِست" className="preset-input" />
          <button className="btn btn-light" onClick={savePreset}>ذخیره پرِست</button>
          {presets.length > 0 && (
            <select onChange={(e) => applyPreset(e.target.value)} className="preset-select">
              <option value="">اعمال پرِست...</option>
              {presets.map(p => (<option key={p.name} value={p.name}>{p.name}</option>))}
            </select>
          )}
        </div>
      </div>

      <div className="actors-grid">
        {filteredActors.length === 0 ? (
          <div className="empty-state">
            <FaUser />
            <p>هیچ عاملی یافت نشد</p>
            <Link to="/actors/new" className="btn btn-success">
              ایجاد اولین عامل
            </Link>
          </div>
        ) : (
          filteredActors.map((actor: any) => (
            <div key={actor.id} className="actor-card">
              <div className="card-header">
                <div className="actor-info">
                  <div className="actor-avatar">
                    <FaUser />
                  </div>
                  <div className="actor-details">
                    <h3>{actor.name}</h3>
                    {actor.role && <p className="actor-role">{actor.role}</p>}
                  </div>
                </div>
                <div className="card-actions">
                  <Link
                    to={`/actors/${actor.id}/edit`}
                    className="action-btn edit"
                    title="ویرایش"
                  >
                    <FaEdit />
                  </Link>
                  <button
                    onClick={() => handleDelete(actor.id)}
                    className="action-btn delete"
                    title="حذف"
                  >
                    <FaTrash />
                  </button>
                </div>
              </div>

              <div className="card-content">
                {actor.phone && (
                  <div className="info-item">
                    <span className="label">تلفن:</span>
                    <span className="value">{toPersianDigits(actor.phone)}</span>
                  </div>
                )}
                {actor.email && (
                  <div className="info-item">
                    <span className="label">ایمیل:</span>
                    <span className="value">{actor.email}</span>
                  </div>
                )}
                {actor.address && (
                  <div className="info-item">
                    <span className="label">آدرس:</span>
                    <span className="value">{actor.address}</span>
                  </div>
                )}
                {actor.description && (
                  <div className="info-item">
                    <span className="label">توضیحات:</span>
                    <span className="value">{actor.description}</span>
                  </div>
                )}
              </div>

              <div className="card-footer">
                <div className="created-info">
                  ایجاد شده در: {new Date(actor.created_at).toLocaleDateString('fa-IR')}
                </div>
                <div className="status-badge">
                  {actor.status === 'active' ? 'فعال' : 'غیرفعال'}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Actors;
